import React, { useEffect, useState } from "react";
import { useParams, useNavigate } from "react-router-dom";

function ManageParticipantsPage() {
    const { studyId } = useParams();
    const navigate = useNavigate();

    const [participants, setParticipants] = useState([]);
    const [allUsers, setAllUsers] = useState([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);

    const [showInviteModal, setShowInviteModal] = useState(false);
    const [inviteEmail, setInviteEmail] = useState("");
    const [inviting, setInviting] = useState(false);

    const [toast, setToast] = useState({ show: false, text: "", type: "success" });

    // ⭐ SOFT GLOW PARTICLES
    const [particles, setParticles] = useState([]);

    const triggerToast = (text, type = "success") => {
        setToast({ show: true, text, type });
        setTimeout(() => setToast({ show: false }), 3000);
    };

    /* ---------------- FETCH PARTICIPANTS + USERS ---------------- */
    useEffect(() => {
        const fetchData = async () => {
            try {
                const token = localStorage.getItem("token");

                const [pRes, uRes] = await Promise.all([
                    fetch(`http://localhost:8080/api/studies/${studyId}/participants`, {
                        headers: { Authorization: `Bearer ${token}` },
                    }),
                    fetch("http://localhost:8080/api/admin/all-users", {
                        headers: { Authorization: `Bearer ${token}` },
                    }),
                ]);

                if (!pRes.ok) throw new Error("Failed to fetch participants");
                if (!uRes.ok) throw new Error("Failed to fetch user list");

                setParticipants(await pRes.json());
                setAllUsers(await uRes.json());
            } catch (err) {
                console.error("❌ Fetch error:", err);
                setError("Failed to load participants or user data");
            } finally {
                setLoading(false);
            }
        };

        fetchData();
    }, [studyId]);

    /* ---------------- PARTICLES ---------------- */
    useEffect(() => {
        const generated = [...Array(45)].map(() => ({
            id: crypto.randomUUID(),
            size: Math.random() * 3 + 2,
            left: Math.random() * 100,
            top: Math.random() * 100,
            duration: 14 + Math.random() * 10,
            delay: Math.random() * -10,
        }));
        setParticles(generated);
    }, []);

    const handleBack = () => navigate(`/manage-study/${studyId}`);

    /* ---------------- INVITE ---------------- */
    const handleInvite = async () => {
        const email = inviteEmail.trim().toLowerCase();

        const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        if (!emailRegex.test(email)) {
            triggerToast("❌ Invalid email format", "error");
            return;
        }

        const user = allUsers.find(u => u.email?.toLowerCase() === email);
        if (!user) {
            triggerToast("❌ User not found", "error");
            return;
        }

        if (user.role !== "PARTICIPANT") {
            triggerToast("❌ Only PARTICIPANT users can join studies", "error");
            return;
        }

        if (participants.some(p => p.email?.toLowerCase() === email)) {
            triggerToast("⚠ Participant already added", "info");
            return;
        }

        try {
            setInviting(true);
            const token = localStorage.getItem("token");

            const res = await fetch(
                `http://localhost:8080/api/studies/${studyId}/participants/invite`,
                {
                    method: "POST",
                    headers: {
                        Authorization: `Bearer ${token}`,
                        "Content-Type": "application/json",
                    },
                    body: JSON.stringify(email),
                }
            );

            if (!res.ok) throw new Error();

            triggerToast("✅ Invitation sent", "success");
            setInviteEmail("");
            setShowInviteModal(false);

            const refreshed = await fetch(
                `http://localhost:8080/api/studies/${studyId}/participants`,
                { headers: { Authorization: `Bearer ${token}` } }
            );

            if (refreshed.ok) setParticipants(await refreshed.json());
        } catch {
            triggerToast("❌ Failed to send invitation", "error");
        } finally {
            setInviting(false);
        }
    };

    /* ---------------- REMOVE PARTICIPANT ---------------- */
    const handleRemove = async (userId) => {
        try {
            const token = localStorage.getItem("token");

            const res = await fetch(
                `http://localhost:8080/api/studies/${studyId}/participants/${userId}`,
                { method: "DELETE", headers: { Authorization: `Bearer ${token}` } }
            );

            if (!res.ok) throw new Error();

            setParticipants(prev => prev.filter(p => p.id !== userId));
            triggerToast("Participant removed", "success");
        } catch {
            triggerToast("❌ Failed to remove participant", "error");
        }
    };

    if (loading)
        return <div style={styles.loading}>Loading participants...</div>;

    if (error)
        return (
            <div style={styles.error}>
                {error}
                <br />
                <button style={styles.backButton} onClick={handleBack}>
                    ← Back
                </button>
            </div>
        );

    return (
        <div style={styles.container}>

            {/* ⭐ PARTICLES */}
            <div style={styles.particles}>
                {particles.map(p => (
                    <div
                        key={p.id}
                        style={{
                            ...styles.particle,
                            left: `${p.left}%`,
                            top: `${p.top}%`,
                            width: p.size,
                            height: p.size,
                            animationDuration: `${p.duration}s`,
                            animationDelay: `${p.delay}s`,
                        }}
                    ></div>
                ))}
            </div>

            {/* TOAST */}
            {toast.show && (
                <div
                    style={{
                        ...styles.toast,
                        ...(toast.type === "success"
                            ? styles.toastSuccess
                            : toast.type === "error"
                                ? styles.toastError
                                : styles.toastInfo),
                    }}
                >
                    {toast.text}
                </div>
            )}

            {/* NAVBAR */}
            <div style={styles.navbar}>
                <h2 style={styles.navTitle}>Manage Participants</h2>

                <div style={{ display: "flex", gap: "12px" }}>
                    <button
                        style={styles.inviteButton}
                        onClick={() => setShowInviteModal(true)}
                    >
                        ✉ Invite Participant
                    </button>

                    <button style={styles.backButton} onClick={handleBack}>
                        ← Back to Study
                    </button>
                </div>
            </div>

            {/* CONTENT */}
            <div style={styles.centerWrapper}>
                <div style={styles.card}>
                    <h3 style={styles.sectionTitle}>👥 Joined Participants</h3>
                    <p style={styles.sectionDesc}>
                        These participants are currently part of this study.
                    </p>

                    {participants.length === 0 ? (
                        <p style={styles.emptyMessage}>No participants yet.</p>
                    ) : (
                        <div style={styles.list}>
                            {participants.map((p) => (
                                <div key={p.id} style={styles.participantCard}>

                                    {/* LEFT SIDE: USER INFO + PROGRESS */}
                                    <div style={{ flex: 1 }}>
                                        <h4 style={styles.participantName}>
                                            {p.name || `${p.firstname} ${p.lastname}`}
                                        </h4>
                                        <p style={styles.participantEmail}>
                                            {p.email}
                                        </p>

                                        {/* ✅ PROGRESS BAR */}
                                        <div style={styles.progressWrapper}>
                                            <div
                                                style={{
                                                    ...styles.progressBar,
                                                    width: `${Math.round(p.progress || 0)}%`,
                                                }}
                                            />
                                        </div>

                                        <p style={styles.progressText}>
                                            Progress: {Math.round(p.progress || 0)}%
                                        </p>
                                    </div>

                                    {/* RIGHT SIDE: REMOVE BUTTON */}
                                    <button
                                        style={styles.removeButton}
                                        onClick={() => handleRemove(p.id)}
                                    >
                                        🗑 Remove
                                    </button>

                                </div>
                            ))}
                        </div>
                    )}
                </div>
            </div>

            {/* INVITE MODAL */}
            {showInviteModal && (
                <div style={styles.modalOverlay}>
                    <div style={styles.modal}>
                        <h3 style={styles.modalTitle}>Invite Participant</h3>
                        <p style={styles.modalDesc}>
                            Enter the participant’s email to send an invitation.
                        </p>

                        <input
                            type="email"
                            placeholder="participant@example.com"
                            value={inviteEmail}
                            onChange={(e) => setInviteEmail(e.target.value)}
                            style={styles.modalInput}
                        />

                        <div style={styles.modalButtons}>
                            <button
                                style={{ ...styles.modalCancel }}
                                className="modal-btn"
                                onClick={() => setShowInviteModal(false)}
                                disabled={inviting}
                            >
                                Cancel
                            </button>

                            <button
                                style={{
                                    ...styles.modalSubmit,
                                    ...(inviting
                                        ? { opacity: 0.6, cursor: "wait" }
                                        : {}),
                                }}
                                className="modal-btn"
                                onClick={handleInvite}
                                disabled={inviting}
                            >
                                {inviting ? "Sending..." : "Send Invite"}
                            </button>
                        </div>
                    </div>
                </div>
            )}

            {/* Hover scale inject */}
            <style>
                {`
                .modal-btn:hover {
                    transform: scale(1.07) !important;
                }
                `}
            </style>
        </div>
    );
}

